CREATE TABLE public.settings (id int primary key default 1, upi_id text not null default '', min_deposit int not null default 100, build_price int not null default 0, updated_at timestamptz not null default now()); GRANT ALL ON public.settings TO service_role; ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY; CREATE TABLE public.wallets (uid text primary key, email text not null default '', balance int not null default 0, updated_at timestamptz not null default now()); GRANT ALL ON public.wallets TO service_role; ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY; CREATE TABLE public.deposit_requests (id uuid primary key default gen_random_uuid(), uid text not null, user_email text not null default '', amount int not null, utr text not null default '', status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); GRANT ALL ON public.deposit_requests TO service_role; ALTER TABLE public.deposit_requests ENABLE ROW LEVEL SECURITY;